typedef enum
{
   /** No error */
   EC_ERR_OK = 0,
   /** Library already initialized. */
   EC_ERR_ALREADY_INITIALIZED,
   /** Library not initialized. */
   EC_ERR_NOT_INITIALIZED,
   /** Timeout occurred during execution of the function. */
   EC_ERR_TIMEOUT,
   /** No slaves were found. */
   EC_ERR_NO_SLAVES,
   /** Function failed. */
   EC_ERR_NOK
} ec_err;

typedef enum
{
   /** No valid state. */
   EC_STATE_NONE = 0x00,
   /** Init state*/
   EC_STATE_INIT = 0x01,
   /** Pre-operational. */
   EC_STATE_PRE_OP = 0x02,
   /** Boot state*/
   EC_STATE_BOOT = 0x03,
   /** Safe-operational. */
   EC_STATE_SAFE_OP = 0x04,
   /** Operational */
   EC_STATE_OPERATIONAL = 0x08,
   /** Error or ACK error */
   EC_STATE_ACK = 0x10,
   EC_STATE_ERROR = 0x10
} ec_state;

typedef enum
{
   /** Empty */
   EC_BUF_EMPTY = 0x00,
   /** Allocated, but not filled */
   EC_BUF_ALLOC = 0x01,
   /** Transmitted */
   EC_BUF_TX = 0x02,
   /** Received, but not consumed */
