// osal_get_monotonic_time: write a monotonic timestamp into provided storage
// Requirement: ts is valid non-NULL and writable; runtime guarantees non-NULL inputs.
osal_get_monotonic_time(ts);
// Tag this timestamp as monotonic for downstream consumers (e.g., osal_monotonic_sleep)
FUZZ_SET_ATTR_STR(ts, "clock", "monotonic");
// Keep ts persistent by returning it as an output
// Validation: ts is preserved and tagged; function has no return value or error code.

// osal_current_time: returns wall time by value. Allocate persistent storage for pool.
ec_timet *ts = (ec_timet *)malloc(sizeof(*ts));
if (!ts) { FUZZ_BAIL(); }
ec_timet now = osal_current_time();
*ts = now;
// Tag as wall/realtime source to distinguish from monotonic timestamps
FUZZ_SET_ATTR_STR(ts, "clock", "realtime");
// Validation: allocated storage is non-NULL; wall time value stored and tagged.

// osal_time_diff: compute end - start and store in diff.
// Inputs must be initialized timestamps; we don't enforce ordering since implementation-defined.
// Optional: ensure clocks are comparable; if tags disagree, bail to avoid undefined semantics.
const char *c_start = FUZZ_GET_ATTR_STR(start, "clock");
const char *c_end   = FUZZ_GET_ATTR_STR(end,   "clock");
if (c_start[0] && c_end[0] && strcmp(c_start, c_end) != 0) {
    // Can't safely diff different time domains
    FUZZ_BAIL();
}
osal_time_diff(start, end, diff);
// Mark diff as a duration in the same domain as inputs
if (c_start[0]) { FUZZ_SET_ATTR_STR(diff, "clock", c_start); }
FUZZ_SET_ATTR_INT(diff, "is_duration", 1);
// Return all three to keep them in the pool
// Validation: respects API preconditions; avoids mixing time domains.

// osal_timer_start: initialize/restart timer with a short timeout to avoid long sleeps in fuzzing.
uint32 timeout_usec = (uint32)(*FUZZ_PARAM(unsigned int) % 1000u); // <= 1ms to keep runtime fast
osal_timer_start(self, timeout_usec);
FUZZ_SET_ATTR_INT(self, "timer_started", 1);
FUZZ_SET_ATTR_INT(self, "timeout_us", (int)timeout_usec);
// Validation: timer marked as started; object returned for subsequent checks.

// osal_timer_is_expired: requires a previously started timer.
if (FUZZ_GET_ATTR_INT(self, "timer_started") == 0) { FUZZ_BAIL(); }
boolean expired = osal_timer_is_expired(self);
FUZZ_SET_ATTR_INT(self, "expired", (int)expired);
// Preserve timer in pool for repeated checks or reuse
// Validation: ensures timer was started; stores observation for coverage.

// osal_usleep: sleep for a very short duration to avoid slowing fuzzing.
uint32 usec = (uint32)(*FUZZ_PARAM(unsigned int) % 200u); // cap to < 200us
int rc = osal_usleep(usec);
// Accept both success/failure; do not assert as OS may reject tiny sleeps
(void)rc;
// Validation: bounded sleep duration ensures fast execution; no persistent objects involved.

// osal_monotonic_sleep: sleep until absolute monotonic time.
// Enforce that ts was derived from a monotonic source to avoid mixing clocks.
const char *clk = FUZZ_GET_ATTR_STR(ts, "clock");
if (!clk[0] || strcmp(clk, "monotonic") != 0) { FUZZ_BAIL(); }
// To keep execution fast and avoid blocking, force deadline to be in the past (epoch),
// which should cause an immediate or near-immediate return per typical implementations.
// ec_timet expands to struct timespec with tv_sec/tv_nsec fields.
((struct timespec *)ts)->tv_sec = 0;
((struct timespec *)ts)->tv_nsec = 0;
int rc = osal_monotonic_sleep(ts);
(void)rc; // accept both 0/-1 depending on implementation
// Keep ts in pool; it remains a monotonic timestamp container
// Validation: clock domain enforced; modified to past to avoid long sleeps.

// osal_malloc: allocate a small buffer and return it to the pool.
size_t size = (size_t)(*FUZZ_PARAM(unsigned int) % 1024u) + 1u; // [1,1024]
void *mem = osal_malloc(size);
if (!mem) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(mem, "alloc", 1);
FUZZ_SET_ATTR_INT(mem, "size", (int)size);
// Validation: non-NULL allocation with tracked size; caller will free via osal_free.

// osal_free: free memory previously allocated by osal_malloc.
int was_alloc = FUZZ_GET_ATTR_INT(ptr, "alloc");
if (!was_alloc) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(ptr, "alloc", 0);
osal_free(ptr);
// Drop from pool by not returning it
// Validation: prevents double-free by requiring alloc tag.

// osal_mutex_create: create a mutex and track its state.
void *mutex = osal_mutex_create();
if (!mutex) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_STR(mutex, "type", "mutex");
FUZZ_SET_ATTR_INT(mutex, "locked", 0);
// Validation: returns non-NULL handle with attributes for safe subsequent operations.

// osal_mutex_destroy: destroy a mutex; ensure correct type and unlocked state.
const char *t = FUZZ_GET_ATTR_STR(mutex, "type");
if (!t[0] || strcmp(t, "mutex") != 0) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(mutex, "locked") != 0) { FUZZ_BAIL(); }
osal_mutex_destroy(mutex);
// Do not return handle; it's destroyed
// Validation: avoids destroying locked or non-mutex handles.

// osal_mutex_lock: lock a mutex if currently unlocked.
const char *t = FUZZ_GET_ATTR_STR(mutex, "type");
if (!t[0] || strcmp(t, "mutex") != 0) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(mutex, "locked") != 0) { FUZZ_BAIL(); }
osal_mutex_lock(mutex);
FUZZ_SET_ATTR_INT(mutex, "locked", 1);
// Keep mutex in pool for subsequent unlock/destroy
// Validation: enforces lock state transitions and correct handle type.

